from collections import Counter
class Solution:
    def firstUniqueFrequency(self, nums):
        cnt = Counter(nums)
        freqCnt = Counter(cnt.values())
        for x in nums:
            if freqCnt[cnt[x]] == 1:
                return x
        return -1

