class Solution {
public:
    int firstUniqueFrequency(vector<int>& nums) {
        unordered_map<int, int> cnt, freqCnt;
        for (int x : nums) cnt[x]++;
        for (auto& [v, f] : cnt) freqCnt[f]++;
        for (int x : nums)
            if (freqCnt[cnt[x]] == 1) return x;
        return -1;
    }
};

