class Solution {
    public int firstUniqueFrequency(int[] nums) {
        Map<Integer, Integer> cnt = new HashMap<>(), freqCnt = new HashMap<>();
        for (int x : nums) cnt.merge(x, 1, Integer::sum);
        for (int f : cnt.values()) freqCnt.merge(f, 1, Integer::sum);
        for (int x : nums)
            if (freqCnt.get(cnt.get(x)) == 1) return x;
        return -1;
    }
}

