        cnt = [0] * MAXV
        for x in nums:
            cnt[x] += 1
        freqCnt = [0] * (len(nums) + 1)
        for x in range(MAXV):
            if cnt[x]:
                freqCnt[cnt[x]] += 1
        for x in nums:
            if freqCnt[cnt[x]] == 1:
                return x
